<template>
 <main class="lecture-page">
  <header class="lecture-heading"><div><span class="eyebrow">校园学术生活</span><h1>讲座与日历</h1><p>发现校内讲座、学术沙龙与活动回顾，时间地点以原通知为准。</p></div><el-button v-if="canManage" @click="openCollector"><el-icon><Setting/></el-icon>采集与导入</el-button></header>
  <section class="lecture-overview" aria-label="讲座概览"><div><strong>{{data.counts.all}}</strong><span>资料记录</span></div><div><strong>{{data.counts.upcoming}}</strong><span>有日期的待开展预告</span></div><div><strong>{{data.counts.undated}}</strong><span>活动日期未明确</span></div><small>{{data.updatedAt?'资料更新于 '+formatStamp(data.updatedAt):'尚未导入讲座资料'}}</small></section>
  <section class="lecture-toolbar" aria-label="讲座筛选">
   <el-input v-model="q" clearable placeholder="搜索主题、主讲人、地点" aria-label="搜索讲座"><template #prefix><el-icon><Search/></el-icon></template></el-input>
   <el-select v-model="campus" clearable placeholder="全部校区" aria-label="筛选校区"><el-option v-for="c in data.campuses" :key="c" :label="c" :value="c"/></el-select>
   <el-select v-model="source" clearable placeholder="全部来源" aria-label="筛选来源"><el-option v-for="s in data.sources" :key="s.id" :label="s.name" :value="s.id"/></el-select>
   <el-select v-model="kind" clearable placeholder="预告与回顾" aria-label="活动资料类型"><el-option label="活动预告" value="preview"/><el-option label="活动回顾" value="review"/><el-option label="其他资料" value="info"/></el-select>
  </section>
  <div class="lecture-controls"><div class="segmented" aria-label="呈现方式"><button :class="{active:view==='calendar'}" :aria-pressed="view==='calendar'" @click="view='calendar'"><el-icon><Calendar/></el-icon>月历</button><button :class="{active:view==='list'}" :aria-pressed="view==='list'" @click="view='list'"><el-icon><List/></el-icon>列表</button></div><el-select v-model="scope" aria-label="时间范围"><el-option label="全部资料" value="all"/><el-option label="待开展预告" value="upcoming"/><el-option label="日期未明确" value="undated"/></el-select></div>
  <el-alert v-if="error" :title="error" type="error" show-icon :closable="false"><el-button text @click="load">重新读取</el-button></el-alert>
  <el-alert v-else-if="!busy&&!data.enabled" title="讲座知识库暂未启用" description="管理员可在知识库中开启校园讲座聚合库。关闭时日历和 Agent 查询同步停用。" type="info" :closable="false"/>
  <section v-if="view==='calendar'&&scope!=='undated'" class="calendar-panel" :aria-busy="busy">
   <header><el-button aria-label="上个月" @click="shiftMonth(-1)"><el-icon><Back/></el-icon></el-button><label><span class="sr-only">选择月份</span><input v-model="month" type="month" min="2000-01" max="2099-12" aria-label="选择月份"/></label><el-button aria-label="下个月" @click="shiftMonth(1)"><el-icon><ArrowRight/></el-icon></el-button><el-button text @click="goToday">本月</el-button></header>
   <div class="week-labels"><span v-for="d in ['一','二','三','四','五','六','日']" :key="d">{{d}}</span></div>
   <div class="calendar-grid"><button v-for="cell in cells" :key="cell.key" :disabled="!cell.date" :class="{today:cell.date===data.today,selected:!!cell.date&&cell.date===selectedDate,muted:!cell.date}" :aria-label="cell.date?cell.date+'，'+(data.days[cell.date]||0)+' 条活动':'空白日期'" :aria-pressed="!!cell.date&&cell.date===selectedDate" @click="selectDate(cell.date)"><span>{{cell.day}}</span><small v-if="cell.date&&data.days[cell.date]">{{data.days[cell.date]}} 条</small></button></div>
   <p>仅按资料中的活动日期排入日历；未明确日期的资料可切换“日期未明确”查看。</p>
  </section>
  <section class="lecture-results" :aria-busy="busy"><header><h2>{{selectedDate&&view==='calendar'?selectedDate+' 的活动':scope==='undated'?'日期未明确的资料':view==='calendar'?month+' 的活动':'讲座资料'}}</h2><span>{{busy?'正在读取…':data.total+' 条'}}</span><el-button v-if="selectedDate" text @click="selectedDate=''">查看整月</el-button></header>
   <div v-if="busy&&!data.items.length" class="lecture-skeleton" role="status" aria-label="正在读取讲座"><div v-for="i in 3" :key="i"/></div>
   <el-empty v-else-if="!data.items.length&&!error" :description="scope==='upcoming'?'暂无有明确日期的待开展预告，可浏览全部或历史资料。':'当前筛选没有资料，试试其他月份、校区或来源。'"/>
   <article v-for="l in data.items" :key="l.id" class="lecture-card"><div class="lecture-date"><span>{{l.event_date?l.event_date.slice(0,7):'日期'}}</span><strong>{{l.event_date?l.event_date.slice(8):'待定'}}</strong><small>{{l.time_text||'时段未注明'}}</small></div><div class="lecture-main"><div class="lecture-tags"><span>{{kindLabels[l.content_kind]||'活动资料'}}</span><span>{{l.type}}</span><span v-if="l.event_date&&l.event_date<data.today">历史资料</span></div><h3><button @click="showDetail(l.id)">{{l.title}}</button></h3><p>{{l.speaker?'主讲：'+l.speaker+' · ':''}}{{l.campus}}{{l.location?' · '+l.location:''}}</p><small>{{l.source_name||l.org}}<template v-if="l.published"> · 发布于 {{l.published}}</template></small></div><button class="detail-action" @click="showDetail(l.id)" :aria-label="'阅读 '+l.title"><el-icon><ArrowRight/></el-icon></button></article>
   <nav v-if="data.total>data.pageSize" class="lecture-pagination" aria-label="讲座分页"><el-button :disabled="page<=1||busy" @click="page--">上一页</el-button><span>{{page}} / {{Math.ceil(data.total/data.pageSize)}}</span><el-button :disabled="page*data.pageSize>=data.total||busy" @click="page++">下一页</el-button></nav>
  </section>
  <el-dialog v-model="detailVisible" title="讲座详情" width="min(720px, calc(100vw - 24px))" destroy-on-close><div v-if="detailBusy" class="detail-status">正在读取详情…</div><el-alert v-else-if="detailError" :title="detailError" type="error" :closable="false"/><template v-else-if="detail"><h2 class="detail-title">{{detail.title}}</h2><dl class="lecture-facts"><div><dt>活动日期</dt><dd>{{detail.event_date||'未明确'}} {{detail.time_text}}</dd></div><div><dt>地点</dt><dd>{{detail.campus}} · {{detail.location||'未注明'}}</dd></div><div><dt>主讲人</dt><dd>{{detail.speaker||'未注明'}}</dd></div><div><dt>来源</dt><dd>{{detail.source_name}} · {{kindLabels[detail.content_kind]||'活动资料'}}</dd></div></dl><p class="lecture-caution">{{detail.date_confidence==='inferred'?'年份根据原文发布日期推定，请先核对原通知。':'字段由公开原文提取，活动变更、报名与准入要求请核对原通知。'}}</p><div class="detail-actions"><a :href="detail.url" target="_blank" rel="noopener noreferrer">查看原通知 <el-icon><TopRight/></el-icon></a><el-button v-if="detail.event_date" @click="downloadCalendar">下载日历 .ics</el-button></div><p v-if="detail.summary" class="lecture-body">{{detail.summary}}</p><p class="lecture-body">{{detail.excerpt||'该记录暂时只有目录信息，请打开原通知查看。'}}</p></template></el-dialog>
  <el-dialog v-model="collectorVisible" title="公开网页讲座采集" width="min(900px, calc(100vw - 24px))" destroy-on-close>
   <p class="collector-intro">从学校公开栏目发现文章，再解析讲座详情、去重并增量写入知识库。不需要扫码；公众号仅处理栏目中已有的公开文章链接，遇到访问限制会报告失败。</p>
   <el-alert v-if="collectorError" :title="collectorError" type="error" :closable="false"/>
   <template v-if="config"><el-form label-position="top"><div class="collector-options"><el-form-item label="定时自动采集"><el-switch v-model="config.enabled"/></el-form-item><el-form-item label="校园网直连（仅学校域名 10.27 网段）"><el-switch v-model="config.campusNetwork"/></el-form-item><el-form-item label="间隔（分钟）"><el-input-number v-model="config.intervalMinutes" :min="60" :max="10080"/></el-form-item><el-form-item label="每栏目最多页数"><el-input-number v-model="config.maxPages" :min="1" :max="5"/></el-form-item><el-form-item label="每次最多有效文章"><el-input-number v-model="config.maxArticles" :min="1" :max="100"/></el-form-item></div>
   <div class="collector-source-heading"><h3>栏目来源 {{config.sources.length}}</h3><el-button @click="addSource" :disabled="config.sources.length>=50">添加栏目</el-button></div><div class="collector-sources"><div v-for="s in config.sources" :key="s.id" class="collector-source"><el-switch v-model="s.enabled" :aria-label="s.name+' 启用'"/><div><el-input v-model="s.name" placeholder="来源名称" :aria-label="s.id+' 名称'"/><el-input v-model="s.url" placeholder="https://学院.ucass.edu.cn/栏目.htm" :aria-label="s.id+' 地址'"/></div><el-select v-model="s.mode" :aria-label="s.id+' 匹配方式'"><el-option label="全部条目" value="all"/><el-option label="讲座关键词" value="filter"/></el-select><el-button text type="danger" @click="config.sources=config.sources.filter((x:any)=>x.id!==s.id)">移除</el-button></div></div></el-form>
   <div class="collector-actions"><el-button type="primary" :loading="saving" @click="saveConfig">保存配置</el-button><el-select v-model="testSource" placeholder="选择要测试的栏目" aria-label="测试来源"><el-option v-for="s in config.sources" :key="s.id" :label="s.name" :value="s.id"/></el-select><el-button :loading="testing" @click="testCollector">测试采集</el-button><el-button :loading="queueing" :disabled="status.status==='SYNCING'" @click="runCollector">按已保存配置采集</el-button></div>
   <p class="collector-note">测试最多读取所选栏目的 3 篇详情，不写入知识库。自动采集仅在知识库开启时运行；短时超时、空结果或栏目缺失均保留历史资料。手动采集在后台运行，刷新页面后仍可查看状态。</p>
   <section class="collector-report"><header><strong>任务状态：{{statusLabels[status.status]||status.status||'尚未采集'}}</strong><el-button text @click="loadStatus">刷新状态</el-button></header><p v-if="status.error">{{status.error}}</p><p v-if="status.summary">已发现 {{status.summary.scanned||0}} · 采集 {{status.summary.collected||0}} · 新增 {{status.summary.created||0}} · 更新 {{status.summary.changed||0}}</p><p v-for="w in status.summary?.warnings||[]" :key="w">{{w}}</p><template v-if="testResult"><h4>测试结果：{{testResult.records.length}} 篇有效文章</h4><p v-for="r in testResult.records" :key="r.id">{{r.title}} · {{r.event_date||'日期未明确'}}</p><p v-for="w in testResult.warnings" :key="w">{{w}}</p></template></section>
   </template>
   <section class="lecture-import"><h3>导入讲座 JSON</h3><p>兼容 lectures 数组导出包或条目数组，按来源链接增量合并，保留知识库开关与历史记录。</p><input ref="fileInput" type="file" accept="application/json,.json" :disabled="importing" @change="importFile"/><progress v-if="importing" :value="importProgress" max="100" aria-label="讲座导入进度"/><span v-if="importing">{{importProgress}}%</span></section>
  </el-dialog>
 </main>
</template>

<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import {get,post,put,toastError,toastOk} from '@/api/client'
import {useAuthStore} from '@/stores/auth'
defineOptions({name:'lecture-calendar'})
const props=defineProps<{studentMode?:boolean}>()
const route=useRoute(),auth=useAuthStore(),canManage=computed(()=>!props.studentMode&&auth.can('campus:admin'))
const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())
const data=ref<any>({counts:{all:0,upcoming:0,undated:0},items:[],sources:[],campuses:[],types:[],days:{},total:0,pageSize:20,today,enabled:true})
const q=ref(''),campus=ref(''),source=ref(''),kind=ref(''),scope=ref('all'),view=ref('calendar'),month=ref(today.slice(0,7)),selectedDate=ref(''),page=ref(1),busy=ref(false),error=ref('')
const detailVisible=ref(false),detail=ref<any>(null),detailBusy=ref(false),detailError=ref('')
const collectorVisible=ref(false),config=ref<any>(null),status=ref<any>({}),collectorError=ref(''),testSource=ref(''),testResult=ref<any>(null),saving=ref(false),testing=ref(false),queueing=ref(false),importing=ref(false),importProgress=ref(0),fileInput=ref<HTMLInputElement>()
const kindLabels:Record<string,string>={preview:'活动预告',review:'活动回顾',info:'活动资料'},statusLabels:Record<string,string>={IDLE:'待启动',SYNCING:'后台采集中',SUCCESS:'采集完成',PARTIAL:'部分完成',FAILED:'未完成'}
let serial=0,detailSerial=0,timer:ReturnType<typeof setTimeout>|undefined,poll:ReturnType<typeof setInterval>|undefined
const formatStamp=(value:string)=>new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',dateStyle:'medium',timeStyle:'short'}).format(new Date(value))
const cells=computed(()=>{
 if(!/^20\d{2}-(0[1-9]|1[0-2])$/.test(month.value))return []
 const [year,m]=month.value.split('-').map(Number),offset=(new Date(Date.UTC(year,m-1,1)).getUTCDay()+6)%7,total=new Date(Date.UTC(year,m,0)).getUTCDate()
 return Array.from({length:Math.ceil((offset+total)/7)*7},(_,i)=>{const day=i-offset+1,valid=day>0&&day<=total;return {key:i,day:valid?day:'',date:valid?month.value+'-'+String(day).padStart(2,'0'):''}})
})
function shiftMonth(delta:number){const [y,m]=month.value.split('-').map(Number),date=new Date(Date.UTC(y,m-1+delta,1));month.value=date.toISOString().slice(0,7)}
function goToday(){month.value=today.slice(0,7);selectedDate.value=''}
function selectDate(date:string){selectedDate.value=selectedDate.value===date?'':date}
async function load(){const current=++serial;busy.value=true;error.value='';try{const result=await get<any>('/lectures',{q:q.value,campus:campus.value,source:source.value,kind:kind.value,scope:scope.value,month:view.value==='calendar'&&scope.value!=='undated'?month.value:undefined,date:view.value==='calendar'&&scope.value!=='undated'?selectedDate.value:undefined,page:page.value});if(current===serial)data.value=result}catch(e){if(current===serial)error.value='讲座资料读取失败，请重试'}finally{if(current===serial)busy.value=false}}
function scheduleLoad(){clearTimeout(timer);serial++;busy.value=true;timer=setTimeout(load,200)}
watch([q,campus,source,kind,scope,view,month],()=>{page.value=1;selectedDate.value='';scheduleLoad()})
watch(selectedDate,()=>{page.value=1;scheduleLoad()});watch(page,scheduleLoad)
async function showDetail(id:string){const current=++detailSerial;detailVisible.value=true;detail.value=null;detailBusy.value=true;detailError.value='';try{const result=await get<any>('/lectures/'+encodeURIComponent(id));if(current===detailSerial)detail.value=result}catch{if(current===detailSerial)detailError.value='详情无法读取，资料可能已停用，请刷新列表后重试'}finally{if(current===detailSerial)detailBusy.value=false}}
function downloadCalendar(){if(!detail.value?.event_date)return;const l=detail.value,escape=(value:string)=>String(value||'').replace(/\\/g,'\\\\').replace(/\r?\n/g,'\\n').replace(/;/g,'\\;').replace(/,/g,'\\,')
 const start=l.event_date.replace(/-/g,''),end=new Date(l.event_date+'T00:00:00Z');end.setUTCDate(end.getUTCDate()+1)
 const text=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//CAgent//Campus Lectures//ZH','BEGIN:VEVENT','UID:'+l.id+'@cagent','DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,''),'DTSTART;VALUE=DATE:'+start,'DTEND;VALUE=DATE:'+end.toISOString().slice(0,10).replace(/-/g,''),'SUMMARY:'+escape(l.title),'LOCATION:'+escape(l.location),'DESCRIPTION:'+escape((l.time_text||'时段未注明')+'\n时间地点请核对原通知\n'+l.url),'URL:'+l.url,'END:VEVENT','END:VCALENDAR',''].join('\r\n')
 const url=URL.createObjectURL(new Blob([text],{type:'text/calendar;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='校园讲座-'+l.event_date+'.ics';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)
}
async function openCollector(){collectorVisible.value=true;collectorError.value='';try{config.value=await get('/lectures/collector/config');testSource.value=config.value.sources[0]?.id||'';await loadStatus()}catch{collectorError.value='采集配置读取失败，请关闭后重试'}}
async function loadStatus(){try{status.value=await get('/lectures/collector/status')}catch{collectorError.value='任务状态读取失败，请重试'}}
function addSource(){config.value.sources.push({id:'source-'+Date.now(),name:'新栏目',url:'',mode:'filter',enabled:true})}
async function saveConfig(){saving.value=true;try{config.value=await put('/lectures/collector/config',config.value);toastOk('采集配置已保存')}catch(e){toastError(e,'配置保存失败')}finally{saving.value=false}}
async function testCollector(){if(!testSource.value)return;testing.value=true;collectorError.value='';try{const input={...config.value,sources:config.value.sources.map((s:any)=>({...s,enabled:s.id===testSource.value}))};testResult.value=await post('/lectures/collector/test',input)}catch(e){toastError(e,'测试失败，请核对来源地址')}finally{testing.value=false}}
async function runCollector(){queueing.value=true;try{await post('/lectures/collector/run',{});toastOk('已开始后台采集');await loadStatus()}catch(e){toastError(e,'任务未启动')}finally{queueing.value=false}}
async function importFile(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;importing.value=true;importProgress.value=0;try{if(file.size>8*1024*1024)throw new Error('文件不能超过 8 MiB');const value=JSON.parse(await file.text()),records=Array.isArray(value)?value:value.lectures;if(!Array.isArray(records)||!records.length||records.length>10000)throw new Error('请上传包含 1–10000 条记录的 lectures 数组');for(let i=0;i<records.length;i+=50){await post('/lectures/import',{records:records.slice(i,i+50)});importProgress.value=Math.round(Math.min(i+50,records.length)/records.length*100)}toastOk('讲座已增量导入');await load();await loadStatus()}catch(e){toastError(e,'导入未完成；已完成批次保留，可重新上传继续')}finally{importing.value=false;if(fileInput.value)fileInput.value.value=''}}
watch(collectorVisible,visible=>{clearInterval(poll);if(visible)poll=setInterval(()=>{if(status.value.status==='SYNCING')void loadStatus()},5000)})
onMounted(()=>{if(/^20\d{2}-(0[1-9]|1[0-2])$/.test(String(route.query.month||'')))month.value=String(route.query.month);void load()});onBeforeUnmount(()=>{serial++;detailSerial++;clearTimeout(timer);clearInterval(poll)})
</script>

